/// A command that names itself, for the label tests.
struct NamedCommand {
    value: i32,
}

impl UndoRedoCommand for NamedCommand {
    fn undo(&mut self) -> Result<()> {
        self.value -= 1;
        Ok(())
    }
    fn redo(&mut self) -> Result<()> {
        self.value += 1;
        Ok(())
    }
    fn as_any(&self) -> &dyn Any {
        self
    }
    fn label(&self) -> Option<UndoLabel> {
        Some(UndoLabel::new("widget", "update"))
    }
}

#[test]
fn test_untracked_stack_records_nothing() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();

    // Push one real command first, so `last_pushed_seq` is `Some` going in.
    // Asserting `None` on a manager that has never pushed anything passes
    // whatever the untracked branch does.
    manager
        .add_command_to_stack(
            Box::new(TestCommand::new(Arc::new(Mutex::new(0)), 1)),
            Some(stack),
        )
        .unwrap();
    assert!(manager.last_pushed_seq().is_some());

    manager
        .add_command_to_stack(
            Box::new(TestCommand::new(Arc::new(Mutex::new(0)), 1)),
            Some(UNTRACKED_STACK_ID),
        )
        .unwrap();

    // Neither the named stack nor the global one grew — the command was dropped
    // at the door, which is the whole point: there is nothing left to clear.
    assert_eq!(manager.get_stack_size(stack), 1);
    assert_eq!(manager.get_stack_size(0), 0);
    assert!(!manager.can_undo(None));
    assert_eq!(
        manager.last_pushed_seq(),
        None,
        "an untracked write records nothing, so it must not leave the register \
         naming the entry below it — which is still the head, and which \
         `undo_if_head` would therefore undo"
    );
}

