#[test]
fn test_push_mints_a_sequence_and_head_reports_it() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();

    manager
        .add_command_to_stack(
            Box::new(TestCommand::new(Arc::new(Mutex::new(0)), 1)),
            Some(stack),
        )
        .unwrap();
    let first = manager.last_pushed_seq().expect("a push mints a sequence");
    assert_eq!(manager.head_seq(Some(stack)), Some(first));

    manager
        .add_command_to_stack(
            Box::new(TestCommand::new(Arc::new(Mutex::new(0)), 1)),
            Some(stack),
        )
        .unwrap();
    let second = manager.last_pushed_seq().unwrap();
    assert_ne!(first, second, "sequences are unique");
    assert_eq!(manager.head_seq(Some(stack)), Some(second));
}

#[test]
fn test_undo_if_head_refuses_a_superseded_entry() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();

    manager
        .add_command_to_stack(
            Box::new(TestCommand::new(Arc::new(Mutex::new(0)), 1)),
            Some(stack),
        )
        .unwrap();
    let target = manager.last_pushed_seq().unwrap();

    // Something else happens before the user reaches for "undo that".
    manager
        .add_command_to_stack(
            Box::new(TestCommand::new(Arc::new(Mutex::new(0)), 1)),
            Some(stack),
        )
        .unwrap();

    assert_eq!(
        manager.undo_if_head(Some(stack), target).unwrap(),
        UndoStatus::Superseded
    );
    assert_eq!(
        manager.get_stack_size(stack),
        2,
        "a superseded request must not undo the newer command instead"
    );

    // Once the newer one is gone, the named entry is reachable again.
    manager.undo(Some(stack)).unwrap();
    assert_eq!(
        manager.undo_if_head(Some(stack), target).unwrap(),
        UndoStatus::Undone
    );
    assert_eq!(manager.get_stack_size(stack), 0);
    assert_eq!(
        manager.undo_if_head(Some(stack), target).unwrap(),
        UndoStatus::Empty
    );
}

