    manager
        .begin_composite_labeled(Some(stack), Some(UndoLabel::act("capture_character")))
        .unwrap();
    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();
    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();
    manager.end_composite();

    assert_eq!(manager.get_stack_size(stack), 1);
    assert_eq!(
        manager.undo_label(Some(stack)),
        Some(UndoLabel::act("capture_character")),
        "the group names itself; `widget/update` describes only its least \
         interesting part"
    );
    assert_eq!(
        manager.last_pushed_seq(),
        manager.head_seq(Some(stack)),
        "closing a group mints one sequence, so a toast can name the group — \
         and it must be the group's own, not any older entry's"
    );
    assert_eq!(
        manager
            .undo_if_head(Some(stack), manager.last_pushed_seq().unwrap())
            .unwrap(),
        UndoStatus::Undone,
        "the sequence a toast was handed must still address the group"
    );
