#[test]
fn test_undo_limit_drops_the_oldest_entries() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();
    manager.set_undo_limit(Some(2));
    assert_eq!(manager.undo_limit(), Some(2));

    for _ in 0..5 {
        manager
            .add_command_to_stack(
                Box::new(TestCommand::new(Arc::new(Mutex::new(0)), 1)),
                Some(stack),
            )
            .unwrap();
    }
    assert_eq!(manager.get_stack_size(stack), 2, "the cap holds");

    // The survivors are the newest two: the head is still the last push.
    let last = manager.last_pushed_seq().unwrap();
    assert_eq!(manager.head_seq(Some(stack)), Some(last));
}

