#[test]
fn test_seal_head_stops_the_next_command_merging_into_it() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();
    let counter = Arc::new(Mutex::new(0));

    manager
        .add_command_to_stack(
            Box::new(MergeableCommand::new(counter.clone(), 1)),
            Some(stack),
        )
        .unwrap();
    // Without the seal these two merge; that is the whole point of merging.
    manager.seal_head(Some(stack));
    manager
        .add_command_to_stack(
            Box::new(MergeableCommand::new(counter.clone(), 2)),
            Some(stack),
        )
        .unwrap();

    assert_eq!(
        manager.get_stack_size(stack),
        2,
        "a sealed entry must not absorb the command after it"
    );

    // And the seal is per-entry: the *new* head is open again.
    manager
        .add_command_to_stack(
            Box::new(MergeableCommand::new(counter.clone(), 3)),
            Some(stack),
        )
        .unwrap();
    assert_eq!(
        manager.get_stack_size(stack),
        2,
        "sealing one entry must not stop everything merging forever"
    );
}

