// ── The composite target is released when the group closes ──────────────────

#[test]
fn test_end_composite_frees_the_target_stack() {
    // `begin_composite` refuses a stack other than the one already open. If
    // ending a group left its target set, the first stack to group anything
    // would be the only one that ever could again — and in a process holding
    // one stack per open document, that is every document after the first
    // permanently losing composites.
    let mut manager = UndoRedoManager::new();
    let first = manager.create_new_stack();
    let second = manager.create_new_stack();

    manager.begin_composite(Some(first)).unwrap();
    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(first))
        .unwrap();
    manager.end_composite();

    manager.begin_composite(Some(second)).expect(
        "a closed group must release its target, or every other stack is locked \
         out of compositing for the life of the manager",
    );
    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(second))
        .unwrap();
    manager.end_composite();

    assert_eq!(manager.get_stack_size(first), 1);
    assert_eq!(manager.get_stack_size(second), 1);
}

#[test]
fn test_an_empty_group_also_frees_the_target_stack() {
    let mut manager = UndoRedoManager::new();
    let first = manager.create_new_stack();
    let second = manager.create_new_stack();

    manager.begin_composite(Some(first)).unwrap();
    manager.end_composite();

    assert!(
        manager.begin_composite(Some(second)).is_ok(),
        "a group that recorded nothing still has to let go of its stack"
    );
    manager.end_composite();
}

// ── `last_pushed_seq` is None on every path that records nothing ────────────
//
// The register answers "which entry did the command I just pushed land in", and
// `undo_if_head` refuses to act unless the sequence it is given is still the
// head. A stale register therefore does not merely misreport — it hands a caller
// the number of an *older* entry that IS still the head, and `undo_if_head`
// undoes it. That is the exact confusion the whole sequence mechanism exists to
// prevent, so each record-nothing path gets its own test.

#[test]
fn test_a_command_folded_into_an_open_group_reports_no_sequence() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();

    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();
    let earlier = manager.last_pushed_seq().unwrap();

    manager.begin_composite(Some(stack)).unwrap();
    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();

    assert_eq!(
        manager.last_pushed_seq(),
        None,
        "the group is still open, so nothing has been pushed yet"
    );
    assert_eq!(
        manager.undo_if_head(Some(stack), earlier).unwrap(),
        UndoStatus::Undone,
        "the earlier entry is genuinely still the head — which is why reporting \
         its sequence as the fold's would undo the wrong command"
    );
}

#[test]
fn test_a_group_that_recorded_nothing_reports_no_sequence() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();

    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();
    assert!(manager.last_pushed_seq().is_some());

    manager.begin_composite(Some(stack)).unwrap();
    manager.end_composite();

    assert_eq!(
        manager.last_pushed_seq(),
        None,
        "an empty group is not an entry, so it has no sequence to report"
    );
    assert_eq!(manager.get_stack_size(stack), 1);
}

#[test]
fn test_a_cancelled_group_reports_no_sequence() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();

    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();
    assert!(manager.last_pushed_seq().is_some());

    manager.begin_composite(Some(stack)).unwrap();
    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();
    manager.cancel_composite();

    assert_eq!(
        manager.last_pushed_seq(),
        None,
        "a cancelled group is not history"
    );
}

/// Closing a group onto a stack that has been deleted under it is a caller bug,
/// and the manager is deliberately loud about it in a debug build rather than
/// silently dropping the group — the shape `database::write_guard` uses. In
/// release the assertion is compiled out and the grouped commands stay applied,
/// just not undoable as a unit; `push_entry`'s own missing-stack guard is what
/// keeps *that* path from minting a sequence for an entry it never stored.
///
/// This is the only way to reach either guard: `add_command_to_stack` refuses a
/// missing stack outright, before `push_entry` is ever called.
#[test]
#[cfg(debug_assertions)]
#[should_panic(expected = "does not exist")]
fn test_closing_a_group_onto_a_deleted_stack_is_loud_in_debug() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();

    manager.begin_composite(Some(stack)).unwrap();
    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();
    manager.delete_stack(stack).unwrap();
    manager.end_composite();
}

// ── Events ─────────────────────────────────────────────────────────────────

/// Drain every undo/redo event the hub has queued, as `(kind, data)` pairs.
fn drain(hub: &Arc<EventHub>) -> Vec<(UndoRedoEvent, Option<String>)> {
    let rx = hub.subscribe_receiver();
    let mut out = Vec::new();
    while let Ok(ev) = rx.try_recv() {
        if let Origin::UndoRedo(kind) = ev.origin {
            out.push((kind, ev.data));
        }
    }
    out
}

#[test]
fn test_history_growth_is_announced_and_names_its_stack() {
    // Without this event a subscriber cannot learn that "can undo" just became
    // true: every other undo/redo event announces the *consumption* of history,
    // never its creation, which leaves an Undo menu row with nothing to react to.
    let hub = Arc::new(EventHub::new());
    let mut manager = UndoRedoManager::new();
    manager.set_event_hub(&hub);
    let stack = manager.create_new_stack();
    let counter = Arc::new(Mutex::new(0));
    drain(&hub);

    manager
        .add_command_to_stack(
            Box::new(MergeableCommand::new(counter.clone(), 1)),
            Some(stack),
        )
        .unwrap();
    assert_eq!(
        drain(&hub),
        vec![(UndoRedoEvent::StackChanged, Some(stack.to_string()))],
        "a push announces itself, and says whose history moved"
    );

    // A merge does not grow the stack, but it does change what undoing it does.
    manager
        .add_command_to_stack(
            Box::new(MergeableCommand::new(counter.clone(), 2)),
            Some(stack),
        )
        .unwrap();
    assert_eq!(manager.get_stack_size(stack), 1);
    assert_eq!(
        drain(&hub),
        vec![(UndoRedoEvent::StackChanged, Some(stack.to_string()))],
        "a merge changed the head, so it is a change"
    );

    manager.undo(Some(stack)).unwrap();
    assert_eq!(
        drain(&hub),
        vec![(UndoRedoEvent::Undone, Some(stack.to_string()))]
    );
    manager.redo(Some(stack)).unwrap();
    assert_eq!(
        drain(&hub),
        vec![(UndoRedoEvent::Redone, Some(stack.to_string()))]
    );

    manager.clear_stack(stack);
    assert_eq!(
        drain(&hub),
        vec![(UndoRedoEvent::StackChanged, Some(stack.to_string()))],
        "history can shrink to nothing as well as grow"
    );
}

#[test]
fn test_an_untracked_write_announces_nothing() {
    let hub = Arc::new(EventHub::new());
    let mut manager = UndoRedoManager::new();
    manager.set_event_hub(&hub);
    let stack = manager.create_new_stack();
    drain(&hub);

    manager
        .add_command_to_stack(
            Box::new(TestCommand::new(Arc::new(Mutex::new(0)), 1)),
            Some(UNTRACKED_STACK_ID),
        )
        .unwrap();

    assert!(
        drain(&hub).is_empty(),
        "an untracked write is not history, so there is no history change to \
         announce — a subscriber that repainted here would be repainting for a \
         timer"
    );
    assert_eq!(manager.get_stack_size(stack), 0);
}

// ── The outermost caller owns the group's name ─────────────────────────────

#[test]
fn test_a_nested_group_never_renames_a_named_outer_one() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();

    manager
        .begin_composite_labeled(Some(stack), Some(UndoLabel::act("import_tags")))
        .unwrap();
    manager
        .begin_composite_labeled(Some(stack), Some(UndoLabel::act("create_tag")))
        .unwrap();
    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();
    manager.end_composite();
    manager.end_composite();

    assert_eq!(
        manager.undo_label(Some(stack)),
        Some(UndoLabel::act("import_tags")),
        "the outermost caller describes what the user asked for; an inner step \
         describes only one of its parts"
    );
}

#[test]
fn test_a_nested_group_may_name_an_anonymous_outer_one() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();

    manager.begin_composite(Some(stack)).unwrap();
    manager
        .begin_composite_labeled(Some(stack), Some(UndoLabel::act("create_tag")))
        .unwrap();
    manager
        .add_command_to_stack(Box::new(NamedCommand { value: 0 }), Some(stack))
        .unwrap();
    manager.end_composite();
    manager.end_composite();

    assert_eq!(
        manager.undo_label(Some(stack)),
        Some(UndoLabel::act("create_tag")),
        "an anonymous group takes the first name offered — better than falling \
         back to the least interesting command inside it"
    );
}

// ── The redo branch ────────────────────────────────────────────────────────

#[test]
fn test_redo_stack_size_follows_undo_and_redo() {
    let mut manager = UndoRedoManager::new();
    let stack = manager.create_new_stack();
    let counter = Arc::new(Mutex::new(0));

    manager
        .add_command_to_stack(Box::new(TestCommand::new(counter.clone(), 1)), Some(stack))
        .unwrap();
    assert_eq!(manager.get_redo_stack_size(stack), 0);

    manager.undo(Some(stack)).unwrap();
    assert_eq!(manager.get_redo_stack_size(stack), 1);
    assert_eq!(manager.get_stack_size(stack), 0);

    manager.redo(Some(stack)).unwrap();
    assert_eq!(manager.get_redo_stack_size(stack), 0);
    assert_eq!(manager.get_stack_size(stack), 1);

    // A fresh push abandons the redo branch.
    manager.undo(Some(stack)).unwrap();
    assert_eq!(manager.get_redo_stack_size(stack), 1);
    manager
        .add_command_to_stack(Box::new(TestCommand::new(counter.clone(), 1)), Some(stack))
        .unwrap();
    assert_eq!(manager.get_redo_stack_size(stack), 0);
}
